import { existsSync, readdirSync } from "node:fs";
import path from "node:path";
import { pageFile } from "./blocks";
import { isHook } from "./hooks";
import type { LoadedRegistry } from "./index";

/** Repo-relative path of the generated variant map (gitignored, built by `pnpm gen:variants`). */
export const VARIANT_MAP_PATH = "lib/registry/variants.generated.ts";

export const VARIANT_MAP_HEADER =
  "// Generated by scripts/gen-variants.ts from registry/**/<item>/variants/*.tsx. Do not edit; run `pnpm gen:variants`.";

export interface VariantEntry {
  item: string;
  variant: string;
  /** Repo-relative POSIX path of the variant file. */
  path: string;
}

/** Plain code-point order, so the output is identical on every OS and locale. */
function compare(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * Finds every variant of every item that ships files. An item's folder is the folder of its
 * first file; its variants are the `.tsx` files directly inside `<folder>/variants/`.
 * Throws naming each item that has no `variants/default.tsx`. Hooks have no variants (the item that
 * declares one shows it), so they are skipped.
 */
export function collectVariants(registry: LoadedRegistry, rootDir = process.cwd()): VariantEntry[] {
  const entries: VariantEntry[] = [];
  const missing: string[] = [];

  for (const item of registry.items) {
    const first = item.files[0];
    if (!first || isHook(item)) continue;
    const variantsDir = path.posix.join(path.posix.dirname(first.path), "variants");
    const absolute = path.resolve(rootDir, variantsDir);
    const files = existsSync(absolute)
      ? readdirSync(absolute).filter((file) => file.endsWith(".tsx"))
      : [];
    if (!files.includes("default.tsx")) {
      missing.push(`${item.name} (expected ${variantsDir}/default.tsx)`);
      continue;
    }
    for (const file of files) {
      entries.push({
        item: item.name,
        variant: file.slice(0, -".tsx".length),
        path: `${variantsDir}/${file}`,
      });
    }
  }

  if (missing.length > 0) {
    throw new Error(`Registry items without a default variant:\n  ${missing.join("\n  ")}`);
  }

  return entries.sort((a, b) => compare(a.item, b.item) || compare(a.variant, b.variant));
}

export interface PageEntry {
  block: string;
  /** Repo-relative POSIX path of the block's `page.tsx`. */
  path: string;
}

/** Every page block's route file, by block name, for `/view/<block>` (app/view/[block]). */
export function collectPages(registry: LoadedRegistry): PageEntry[] {
  return registry.items
    .flatMap((item) => {
      const page = pageFile(item);
      return page ? [{ block: item.name, path: page.path }] : [];
    })
    .sort((a, b) => compare(a.block, b.block));
}

/**
 * Renders the variant map module: a data list plus lazy loaders keyed by item, then variant; and the
 * page blocks' routes with a lazy loader each.
 */
export function renderVariantMap(entries: VariantEntry[], pages: PageEntry[] = []): string {
  const byItem = new Map<string, VariantEntry[]>();
  for (const entry of entries) {
    byItem.set(entry.item, [...(byItem.get(entry.item) ?? []), entry]);
  }

  const list = entries.map(
    (entry) =>
      `  { item: ${JSON.stringify(entry.item)}, variant: ${JSON.stringify(entry.variant)}, path: ${JSON.stringify(entry.path)} },`,
  );
  const loaders = [...byItem].map(([item, variants]) => {
    const lines = variants.map(
      (entry) =>
        `    ${JSON.stringify(entry.variant)}: () => import(${JSON.stringify(`@/${entry.path.slice(0, -".tsx".length)}`)}),`,
    );
    return `  ${JSON.stringify(item)}: {\n${lines.join("\n")}\n  },`;
  });

  return [
    VARIANT_MAP_HEADER,
    'import type { ComponentType } from "react";',
    "",
    "export type VariantModule = { default: ComponentType };",
    "export type VariantLoader = () => Promise<VariantModule>;",
    "",
    "export const variantEntries: readonly { item: string; variant: string; path: string }[] = [",
    ...list,
    "];",
    "",
    "export const variantLoaders: Record<string, Record<string, VariantLoader>> = {",
    ...loaders,
    "};",
    "",
    "export const pageEntries: readonly { block: string; path: string }[] = [",
    ...pages.map(
      (page) => `  { block: ${JSON.stringify(page.block)}, path: ${JSON.stringify(page.path)} },`,
    ),
    "];",
    "",
    "export const pageLoaders: Record<string, VariantLoader> = {",
    ...pages.map(
      (page) =>
        `  ${JSON.stringify(page.block)}: () => import(${JSON.stringify(`@/${page.path.slice(0, -".tsx".length)}`)}),`,
    ),
    "};",
    "",
  ].join("\n");
}

/** Repo-relative path of the generated variant list (data only, no loaders; `pnpm gen:variants`). */
export const VARIANT_LIST_PATH = "lib/registry/variant-list.generated.ts";

/**
 * Renders the variant list module: the variants and page blocks as data, with no `import()`. The
 * `/view` and `/gallery` routes read it instead of the variant map: Turbopack gives a route the client
 * code of every module its server code can `import()`, so the map would load the whole
 * registry's client code on each of them (MANGA-21).
 */
export function renderVariantList(entries: VariantEntry[], pages: PageEntry[] = []): string {
  return [
    VARIANT_MAP_HEADER,
    "",
    "export const variantEntries: readonly { item: string; variant: string; path: string }[] = [",
    ...entries.map(
      (entry) =>
        `  { item: ${JSON.stringify(entry.item)}, variant: ${JSON.stringify(entry.variant)}, path: ${JSON.stringify(entry.path)} },`,
    ),
    "];",
    "",
    "export const pageEntries: readonly { block: string; path: string }[] = [",
    ...pages.map(
      (page) => `  { block: ${JSON.stringify(page.block)}, path: ${JSON.stringify(page.path)} },`,
    ),
    "];",
    "",
  ].join("\n");
}

/** Stages that are not an item's variant, served at `/gallery/<item>/<variant>` from app/gallery. */
export const EXTRA_STAGES: readonly { item: string; variant: string; module: string }[] = [
  // The theme specimen: a dozen items' default variants on one page, so one shot shows a look.
  { item: "theme", variant: "specimen", module: "@/app/gallery/theme-specimen" },
];

export interface RouteFile {
  /** Repo-relative POSIX path of the route file. */
  path: string;
  source: string;
}

/** The folders the generated routes live in; every subfolder of these is generated. */
export const ROUTE_ROOTS = ["app/view", "app/gallery"] as const;

const moduleOf = (file: string) => `@/${file.slice(0, -".tsx".length)}`;

/**
 * Renders one static route file per page block (`app/view/<block>/page.tsx`), per item gallery
 * (`app/gallery/<item>/page.tsx`) and per variant stage (`app/gallery/<item>/<variant>/page.tsx`), each
 * importing only its own module, so each route loads only its own client code (MANGA-21). The
 * pages themselves are the shared shells next to them (app/view/block-view.tsx,
 * app/gallery/variant-stage.tsx, app/gallery/item-gallery.tsx). Throws on a name that would collide.
 */
export function renderVariantRoutes(entries: VariantEntry[], pages: PageEntry[] = []): RouteFile[] {
  const header = [VARIANT_MAP_HEADER, 'import type { Metadata } from "next";'];
  const files: RouteFile[] = pages.map((page) => ({
    path: `app/view/${page.block}/page.tsx`,
    source: [
      ...header,
      `import Page from ${JSON.stringify(moduleOf(page.path))};`,
      'import { BlockView, VIEW_METADATA } from "../block-view";',
      "",
      "export const metadata: Metadata = VIEW_METADATA;",
      "",
      "export default function View() {",
      "  return <BlockView page={Page} />;",
      "}",
      "",
    ].join("\n"),
  }));

  const byItem = new Map<string, VariantEntry[]>();
  for (const entry of entries) byItem.set(entry.item, [...(byItem.get(entry.item) ?? []), entry]);
  for (const extra of EXTRA_STAGES) {
    if (byItem.has(extra.item)) throw new Error(`Item "${extra.item}" collides with a stage`);
  }

  for (const [item, variants] of byItem) {
    files.push({
      path: `app/gallery/${item}/page.tsx`,
      source: [
        ...header,
        ...variants.map(
          (entry, index) => `import Variant${index} from ${JSON.stringify(moduleOf(entry.path))};`,
        ),
        'import { GALLERY_METADATA, ItemGallery } from "../item-gallery";',
        "",
        "export const metadata: Metadata = GALLERY_METADATA;",
        "",
        "const variants = {",
        ...variants.map((entry, index) => `  ${JSON.stringify(entry.variant)}: Variant${index},`),
        "};",
        "",
        "export default function Gallery() {",
        `  return <ItemGallery item=${JSON.stringify(item)} variants={variants} />;`,
        "}",
        "",
      ].join("\n"),
    });
  }

  const stages = [
    ...entries.map((entry) => ({ ...entry, module: moduleOf(entry.path) })),
    ...EXTRA_STAGES,
  ];
  for (const stage of stages) {
    files.push({
      path: `app/gallery/${stage.item}/${stage.variant}/page.tsx`,
      source: [
        ...header,
        `import Variant from ${JSON.stringify(stage.module)};`,
        'import { VariantStage, STAGE_METADATA } from "../../variant-stage";',
        "",
        "export const metadata: Metadata = STAGE_METADATA;",
        "",
        "export default function Stage() {",
        `  return <VariantStage item=${JSON.stringify(stage.item)} variant=${JSON.stringify(stage.variant)} component={Variant} />;`,
        "}",
        "",
      ].join("\n"),
    });
  }
  return files;
}
